<?php
// binary, octal and hexadecimal literals past PHP_INT_MAX become floats the
// way php's scanner builds them, digit by digit in a double
var_dump(0b1111111111111111111111111111111111111111111111111111111111111111);
var_dump(0b11111111111111111111111111111111111111111111111111111111111111111);
var_dump(-0b1111111111111111111111111111111111111111111111111111111111111111);
var_dump(01777777777777777777777, 0377777777777777777777777);
var_dump(0xFFFFFFFFFFFFFFFF, 0x1_0000_0000_0000_0000, 0x45FFFABCDE0000000);
var_dump(0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF);
var_dump();
var_dump(9223372036854775807, 9223372036854775808, 0x7FFFFFFFFFFFFFFF, 0777777777777777777777);
